    .unit-vw { font-size: clamp(1rem, 3vw, 2rem); }
    .unit-rem { font-size: 1.5rem; }
    .mode-toggle { padding: 0.5rem 1rem; background: #1572B6; color: #fff; border: none; border-radius: 6px; cursor: pointer; }
    @media (prefers-color-scheme: dark) {
