rust
use std::sync::{Arc, Mutex, mpsc};
use std::thread;
use std::time::Duration;

fn main() {
    let handle = thread::spawn(|| {
        for i in 1..=3 {
            println!("Child thread: {}", i);
            thread::sleep(Duration::from_millis(10));
        }
    });
    handle.join().unwrap();

    let counter = Arc::new(Mutex::new(0));
    let mut handles = vec![];

    for _ in 0..10 {
        let c = Arc::clone(&counter);
        handles.push(thread::spawn(move || {
            let mut num = c.lock().unwrap();
            *num += 1;
        }));
    }

    for h in handles {
        h.join().unwrap();
    }
    println!("Final counter: {}", *counter.lock().unwrap());

    let (tx, rx) = mpsc::channel();
    thread::spawn(move || {
        let msg = String::from("Hello from thread!");
        tx.send(msg).unwrap();
    });

    let received = rx.recv().unwrap();
    println!("Message received: {}", received);
}
Run the program on the right to see the output. This code demonstrates all concepts for this week.

--Explanation

Threads

 — creates a new OS thread.  waits for thread completion.  transfers ownership to the thread closure.

Arc<T>

 — Atomic Reference Counting. Thread-safe version of Rc.  for sharing data across threads.

Mutex<T>

 — mutual exclusion. Only one thread can access data at a time.  because locks can poison.

Channels

 — Multiple Producer, Single Consumer.  sends,  receives. Cloning tx enables multiple producers.

